/** Credentials come from the ENVIRONMENT only; nothing here is read from disk or printed. */
function envDbConfig(): DbConfig | null {
  const pg = process.env.SITEDASH_PG_URL ?? process.env.DATABASE_URL;
  if (pg) return { dialect: "pg", connectionString: pg };
  const host = process.env.SITEDASH_MYSQL_HOST;
  if (!host) return null;
  return {
    dialect: "mysql",
    host,
    port: process.env.SITEDASH_MYSQL_PORT ? Number(process.env.SITEDASH_MYSQL_PORT) : 3306,
    user: process.env.SITEDASH_MYSQL_USER,
    password: process.env.SITEDASH_MYSQL_PASSWORD,
    database: process.env.SITEDASH_MYSQL_DATABASE,
  };
}

let _store: Store | undefined;
function store(): Store {
  if (_store) return _store;
  const cfg = envDbConfig();
  if (!cfg) throw new Error("sitedash: no database configured (set SITEDASH_PG_URL or SITEDASH_MYSQL_*)");
  _store = new KyselyStore(openDb(cfg));
  return _store;
}

export interface ServerContext { deps: DashboardDeps; lead: LeadService; redactLeadFields: (ctx: RequestCtx) => Promise<string[]>; }

let _context: ServerContext | undefined;

/**
 * Wire the tested core store + services + the WHOLE registry deps bag - ONCE per
 * process. AuthService and LeadService each own the in-memory rate limiter that
 * backs the login/lead security mandate, so rebuilding them per request would reset
 * the counters and let a flood straight through.
 *
 * Every callback here answers from the BAKED manifest. That is the point: a host that
 * re-derived these at request time would be guessing at structure the scan already
 * proved, and the API's "unknown page/section/collection" refusals would depend on
 * whatever the process happened to load.
 */
export function loadServerContext(): ServerContext {
  if (_context) return _context;
  const s = store();
  const auth = new AuthService(s);
  const content = new ContentService(s);
  const audit = new AuditService(s);
  const pageIds = TREE.map((p) => p.id);
  const knownPages = new Set(pageIds);
  const knownSections = new Set(KNOWN_SECTIONS);
  const collections = new Map(COLLECTIONS.map((c) => [c.id, c]));
  const knownCtas = new Set(KNOWN_CTA_IDS);
  // Secrets come from the environment only; an absent preview secret simply disables the
  // draft-token path rather than falling back to a hard-coded key.
  const previewSecret = process.env.SITEDASH_PREVIEW_SECRET ?? "";
  // core's own redaction rule, wired with the deps it asks for - so the boot flag the
  // dashboard shows and the refusal the leads API makes cannot disagree.
  const redactLeadFields = makeLeadFieldRedaction({ store: s, auth, audit, previewSecret });
  const deps: DashboardDeps = {
    store: s,
    auth,
    content,
    audit,
    previewSecret,
    locate: (fieldKey) => LOCATE[fieldKey] ?? null,
    sectionsOf: (pageId) => SECTIONS_OF[pageId] ?? [],
    knownPage: (pageId) => knownPages.has(pageId),
    knownSection: (sectionId) => knownSections.has(sectionId),
    pageIds: () => pageIds,
    themeTokens: () => THEME_TOKENS,
    animationsOf: (sectionId) => ANIMATIONS_OF[sectionId] ?? [],
    knownSectionIds: () => KNOWN_SECTIONS,
    mediaIndex: () => MEDIA_INDEX,
    contentRefs: async () => {
      const rows = await s.listContent("published");
      return rows.map((r) => ({ key: r.fieldKey, locale: r.locale, value: r.value }));
    },
    seoSource: (pageId) => SEO_SOURCE[pageId] ?? null,
    contentLocales: () => CONTENT_LOCALES,
    knownCollection: (collectionId) => collections.has(collectionId),
    collectionSchema: (collectionId) => (collections.get(collectionId) ?? { fields: [] }).fields,
    knownCta: (ctaId) => knownCtas.has(ctaId),
    knownCtaIds: () => KNOWN_CTA_IDS,
    leadFieldRedaction: redactLeadFields,
    publish: new PublishService(s, content),
    legacyInput: () => legacyInput(),
  };
  _context = { deps, lead: new LeadService(s), redactLeadFields };
  return _context;
}

/**
 * The legacy dump, read at request time and NEVER interpreted: no file, an unreadable
 * file or a non-object all answer null, and `legacy.plan` then reports "not configured"
 * instead of an empty plan that would read as "nothing to migrate" about a source nobody
 * looked at.
 */
function legacyInput(): LegacyInput | null {
  if (!LEGACY_FILE) return null;
  try {
    const raw = fs.readFileSync(path.resolve(process.cwd(), LEGACY_FILE), "utf8");
    const parsed = JSON.parse(raw) as unknown;
    return parsed && typeof parsed === "object" ? (parsed as LegacyInput) : null;
  } catch {
    return null;
  }
}

/** True when the site has NO user yet - the only honest way to offer "create the Owner". */
export async function isFirstRun(deps: DashboardDeps): Promise<boolean> {
  return (await deps.store.listUsers()).length === 0;
}

/**
 * Which lead fields this viewer's ROLE withholds. Resolved with core's own redaction
 * function (the one the leads API runs), so the boot flag and the API's refusal cannot
 * diverge - and a viewer with no session simply sees nothing redacted.
 */
export async function leadsHiddenFor(user: UserRow | null): Promise<string[]> {
  if (!user) return [];
  const { redactLeadFields } = loadServerContext();
  return redactLeadFields({ userId: user.id, principal: null, csrfOk: false, user });
}

/**
 * Public lead capture. The honeypot + the per-IP rate limit live inside the tested
 * LeadService (one instance for the whole process, so the counter really counts);
 * the Sheet push is an optional side effect that QUEUES when Sheets is unconfigured
 * or unreachable, so a visitor's submission never fails on it.
 */
export async function captureLead(body: Record<string, unknown>, ip?: string) {
  const { deps, lead } = loadServerContext();
  const text = (k: string): string | undefined => (typeof body?.[k] === "string" ? (body[k] as string) : undefined);
  const data = body?.data;
  const res = await lead.submit({
    data: data && typeof data === "object" ? (data as Record<string, unknown>) : {},
    ip,
    source: text("source"),
    page: text("page"),
    locale: text("locale"),
    ctaId: text("ctaId"),
  });
  if (res.ok && res.lead) {
    try {
      await pushLead({ ...deps, post: sheetsPost }, res.lead);
    } catch {
      // the lead is already durable in the DB; the retry queue owns the Sheet
    }
  }
  return res;
}

async function sheetsPost(url: string, payload: string) {
  const r = await fetch(url, {
    method: "POST",
    body: payload,
    headers: { "content-type": "text/plain;charset=utf-8" },
  });
  const textOut = await r.text().catch(() => "");
  return { ok: r.ok, status: r.status, text: textOut.slice(0, 500) };
}

